#!/bin/bash
# Build the probe database for a battery: the Contacts starter template's
# schema with the probe fields (probe_schema.py) and the battery's scripts,
# generated by FMUpgradeTool and scanned by FileMaker's ScanScript in the
# script harness container (no run lines). Prints the built file's path.
# usage: build.sh <battery.txt>
# env: FMS_ROOT, FILES (holding contacts-en.fmp12), WORK, HARNESS_LOCK as for
#      tools/fms-script-harness/runbat.sh
set -e
D=$(cd "$(dirname "$0")" && pwd)
H="$D/../fms-script-harness"
B=$1; name=$(basename "$B" .txt)
: "${WORK:?set WORK}"
mkdir -p "$WORK"
if [ ! -s "$WORK/contacts-en.xml" ]; then
    # runbat.sh saves the file's schema in $WORK before its first patch
    printf '== X\nBeep\n--- run\n' > "$WORK/schema-only.txt"
    SCHEMA= "$H/runbat.sh" "$WORK/schema-only.txt" contacts-en.fmp12 "$WORK" > /dev/null
fi
# ACCOUNTS_XML: a schema document whose AccountsCatalog the probe file takes
# (FileMaker Server opens no file with a passwordless full access account).
python3 -I "$D/probe_schema.py" "$WORK/contacts-en.xml" ${ACCOUNTS_XML:+"$ACCOUNTS_XML"} > "$WORK/probe-en.xml"
awk '/^--- run/ { exit } { print } END { print "--- run" }' "$B" > "$WORK/$name.txt"
SCHEMA="$WORK/probe-en.xml" "$H/runbat.sh" "$WORK/$name.txt" contacts-en.fmp12 "$WORK" > /dev/null
echo "$WORK/$name.contacts-en.gen.run.fmp12"
